function missingNumber(nums) {
  let xor = nums.length;            // seed with n (the index we never visit by value)
  for (let i = 0; i < nums.length; i++) {
    xor ^= i ^ nums[i];             // mix in index i and value nums[i]
  }
  return xor;
}
// Time O(n), Space O(1)

